use leptos::*;

fn main() {
    mount_to_body(|| view! { <App/> });
}

#[component]
fn App() -> impl IntoView {
    let (flow, set_flow) = create_signal(12.0_f64);
    let (area, set_area) = create_signal(8.0_f64);
    let (feed, set_feed) = create_signal(500.0_f64);
    let (permeate, set_permeate) = create_signal(25.0_f64);
    let flux = move || flow.get() / area.get();
    let rejection = move || (1.0 - permeate.get() / feed.get().max(0.001)) * 100.0;
    let recovery = move || flow.get() / 40.0 * 100.0;

    view! {
      <header class="topbar"><a class="brand" href="#home"><span class="brand-mark">"B"</span><span>"BEYOND FILTRATION"<small>"MEMBRANE SEPARATION, EXPLAINED"</small></span></a><nav><a href="#fundamentals">"Fundamentals"</a><a href="#types">"Membrane types"</a><a href="#calculator">"Calculator"</a><a href="#applications">"Applications"</a></nav></header>
      <main>
        <section class="hero" id="home"><div class="hero-copy"><p class="eyebrow">"CHEMICAL ENGINEERING • SEPARATIONS"</p><h1>"A clearer way to separate."<em>" A cleaner way to use water."</em></h1><p class="lead">"Discover how membranes selectively separate components, how engineers evaluate performance, and why this technology matters for water and wastewater treatment."</p><a class="primary" href="#fundamentals">"Explore the process ↓"</a></div><div class="hero-art"><div class="art-label label-feed">"FEED"</div><div class="membrane-visual"><div class="particle p1"></div><div class="particle p2"></div><div class="particle p3"></div><div class="particle p4"></div><div class="membrane-sheet"></div><div class="water-line"></div></div><div class="art-label label-retain">"RETAINED"</div><div class="art-label label-perm">"PERMEATE"</div></div></section>
        <section class="intro section" id="fundamentals"><p class="eyebrow">"01 / THE BIG IDEA"</p><h2>"A selective barrier does the separating."</h2><p class="section-lead">"Membrane separation uses a thin, selective barrier to allow some components to pass while restricting others. A pressure difference commonly drives the process."</p><div class="process-grid"><article class="process-card"><span class="step">"01"</span><h3>"Feed"</h3><p>"The incoming liquid contains the water or product of interest along with dissolved or suspended components."</p></article><article class="process-card"><span class="step">"02"</span><h3>"Membrane"</h3><p>"A selective material separates components according to size, charge, solubility, or other interactions."</p></article><article class="process-card"><span class="step">"03"</span><h3>"Two streams"</h3><p>"Permeate passes through the membrane; retentate remains on the feed side and becomes more concentrated."</p></article></div><div class="stream-diagram"><div class="stream feed-stream">"FEED"<small>"Mixed solution"</small></div><div class="arrow">"→"</div><div class="membrane-block">"SELECTIVE MEMBRANE"</div><div class="split-arrows"><span>"↗"</span><span>"↘"</span></div><div class="stream ret-stream">"RETENTATE"<small>"Rejected components"</small></div><div class="stream perm-stream">"PERMEATE"<small>"Components that pass"</small></div></div></section>
        <section class="section types" id="types"><p class="eyebrow">"02 / MEMBRANE FAMILIES"</p><h2>"Choose the separation scale."</h2><p class="section-lead">"Pressure-driven membrane processes are often grouped by the approximate size of what they retain. Actual cutoffs depend on membrane material and operating conditions."</p><div class="type-grid"><article class="type-card"><div class="type-head"><span>"MF"</span><b>"Microfiltration"</b></div><p class="range">"~0.1–10 µm"</p><p>"Targets suspended solids, many bacteria, and larger particles."</p><small>"COMMON USE: PRETREATMENT, CLARIFICATION"</small></article><article class="type-card"><div class="type-head"><span>"UF"</span><b>"Ultrafiltration"</b></div><p class="range">"~0.01–0.1 µm"</p><p>"Retains colloids, macromolecules, and many viruses."</p><small>"COMMON USE: WATER TREATMENT, MBRs"</small></article><article class="type-card"><div class="type-head"><span>"NF"</span><b>"Nanofiltration"</b></div><p class="range">"~1–2 nm"</p><p>"Separates many organic molecules and multivalent ions."</p><small>"COMMON USE: SOFTENING, ORGANIC REMOVAL"</small></article><article class="type-card"><div class="type-head"><span>"RO"</span><b>"Reverse osmosis"</b></div><p class="range">"Dense, nonporous layer"</p><p>"Rejects most dissolved salts and produces low-salinity water."</p><small>"COMMON USE: DESALINATION, WATER REUSE"</small></article></div></section>
        <section class="section engineering"><p class="eyebrow">"03 / ENGINEERING PERFORMANCE"</p><h2>"Turn separation into measurable performance."</h2><div class="equation-grid"><article><h3>"Permeate flux"</h3><div class="equation">"J = Qₚ / A"</div><p>"Volumetric permeate flow per unit membrane area. Common units: L·m⁻²·h⁻¹."</p></article><article><h3>"Observed rejection"</h3><div class="equation">"R = (1 − Cₚ/Cf) × 100%"</div><p>"The percentage reduction in concentration from feed to permeate."</p></article><article><h3>"Water recovery"</h3><div class="equation">"Y = (Qₚ/Qf) × 100%"</div><p>"The fraction of feed flow converted into permeate."</p></article><article><h3>"Simplified resistance model"</h3><div class="equation">"J = (ΔP − Δπ) / (μ Rₜ)"</div><p>"Flux decreases as hydraulic resistance increases; osmotic pressure opposes the applied pressure."</p></article></div><p class="note">"These are introductory relationships. Detailed design may require concentration-polarization, fouling, temperature, module geometry, and membrane-specific models."</p></section>
        <section class="section calculator" id="calculator"><p class="eyebrow">"04 / INTERACTIVE EXPLORER"</p><h2>"Experiment with operating conditions."</h2><p class="section-lead">"Adjust the values to see how flow, area, and concentration affect common performance metrics. This teaching calculator assumes a feed flow of 40 L/min for recovery."</p><div class="calc-layout"><div class="controls"><label>"Permeate flow"<strong>{move || format!("{:.1} L/min", flow.get())}</strong><input type="range" min="1" max="30" step="0.5" prop:value=flow on:input=move |ev| set_flow.set(event_target_value(&ev).parse().unwrap_or(12.0)) /></label><label>"Membrane area"<strong>{move || format!("{:.1} m²", area.get())}</strong><input type="range" min="1" max="30" step="0.5" prop:value=area on:input=move |ev| set_area.set(event_target_value(&ev).parse().unwrap_or(8.0)) /></label><label>"Feed concentration"<strong>{move || format!("{:.0} mg/L", feed.get())}</strong><input type="range" min="100" max="1500" step="25" prop:value=feed on:input=move |ev| set_feed.set(event_target_value(&ev).parse().unwrap_or(500.0)) /></label><label>"Permeate concentration"<strong>{move || format!("{:.0} mg/L", permeate.get())}</strong><input type="range" min="0" max="500" step="5" prop:value=permeate on:input=move |ev| set_permeate.set(event_target_value(&ev).parse().unwrap_or(25.0)) /></label></div><div class="results"><div><small>"FLUX"</small><strong>{move || format!("{:.2}", flux())}</strong><span>"L·m⁻²·min⁻¹"</span></div><div><small>"OBSERVED REJECTION"</small><strong>{move || format!("{:.1}%", rejection())}</strong><span>"Concentration-based"</span></div><div><small>"RECOVERY"</small><strong>{move || format!("{:.1}%", recovery())}</strong><span>"Assumed feed = 40 L/min"</span></div></div></div></section>
        <section class="section applications" id="applications"><p class="eyebrow">"05 / ENVIRONMENTAL CONNECTIONS"</p><h2>"Membranes are part of the water solution."</h2><div class="application-grid"><article><div class="app-number">"A"</div><h3>"Membrane bioreactors"</h3><p>"Combine biological wastewater treatment with membrane filtration. The membrane retains biomass and suspended solids, producing a clarified effluent."</p></article><article><div class="app-number">"B"</div><h3>"Water reuse"</h3><p>"Membrane trains can help remove particles, microorganisms, and dissolved salts, supporting fit-for-purpose reuse when paired with appropriate treatment and monitoring."</p></article><article><div class="app-number">"C"</div><h3>"Industrial wastewater"</h3><p>"Selective treatment can recover water or valuable materials and reduce the volume or strength of waste streams."</p></article></div><div class="closing"><p class="eyebrow">"THE ENGINEERING CHALLENGE"</p><h3>"A membrane is only as good as the system around it."</h3><p>"Engineers balance separation quality, energy demand, recovery, fouling control, cleaning, concentrate management, and lifecycle cost."</p></div></section>
      </main><footer><span>"BEYOND FILTRATION"</span><span>"A chemical engineering separations project"</span><a href="#home">"Back to top ↑"</a></footer>
    }
}
